class ValueStoreStartupTermIndexCapacityTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@NullAndEmptySource
	@ValueSource(strings = "opsc,posc")
	void standaloneBootstrapPersistsOnlyItsDictionaryLayout(String requested) throws Exception {
		Set<String> expected = requested == null || requested.isEmpty()
				? Set.of("spoc", "cspo")
				: Set.of("spoc", "cspo", "opsc", "posc");
		LmdbStoreConfig config = config().setTripleTermIndexes(requested);
		ValueStore values = new ValueStore(directory.toFile(), config);
		try {
			assertLayout(values, expected);
			StoreProperties saved = readProperties(directory);
			assertThat(saved.getTripleIndexes()).as("a dictionary cannot author statement-index metadata").isNull();
			assertThat(TripleIndex.parseIndexSpecList(saved.getTripleTermIndexes())).isEqualTo(expected);
			assertThat(Files.readString(directory.resolve(LmdbStore.CORE_LITERAL_REFERENCE_MARKER_FILE)))
					.isEqualTo(LmdbStore.CORE_LITERAL_REFERENCE_MARKER);
		} finally {
			values.close();
		}
		ValueStore reopened = new ValueStore(directory.toFile(), config());
		try {
			assertLayout(reopened, expected);
			assertThat(readProperties(directory).getTripleIndexes()).isNull();
		} finally {
			reopened.close();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nativeLayoutControlsCapacityDespiteMissingOrStaleTermSidecar(boolean legacy) throws Exception {
		for (String stale : Arrays.asList(null, "", "spoc,cspo", "not-an-index")) {
			Path path = directory.resolve(stale == null ? "missing" : stale.isEmpty() ? "empty" : stale);
			Seed seed = seed(path, legacy);
			readProperties(path).setTripleTermIndexes(stale).save();
			ValueStore reopened = new ValueStore(path.toFile(), config());
			try {
				assertLayout(reopened, Set.of("spoc", "cspo", "opsc"));
				assertThat(reopened.getId(seed.term(), false)).isEqualTo(seed.id());
				assertThat(reopened.getValue(seed.id())).isEqualTo(seed.term());
				StoreProperties saved = readProperties(path);
				assertThat(TripleIndex.parseIndexSpecList(saved.getTripleTermIndexes()))
						.isEqualTo(Set.of("spoc", "cspo", "opsc"));
				assertThat(saved.getTripleIndexes()).isNull();
				assertThat(reopened.getFormat().isLegacy()).isEqualTo(legacy);
			} finally {
				reopened.close();
			}
		}
	}

	@Test
	void failedFixedCapacityBootstrapKeepsItsLayoutForACompleteRetry() throws Exception {
		LmdbStoreConfig fixed = config().setAutoGrow(false).setTripleTermIndexes("opsc");
		assertThrows(LmdbUtil.MapFullException.class, () -> openAndClose(directory, fixed));
		StoreProperties saved = readProperties(directory);
		assertThat(TripleIndex.parseIndexSpecList(saved.getTripleTermIndexes()))
				.isEqualTo(Set.of("spoc", "cspo", "opsc"));
		assertThat(saved.getTripleIndexes()).isNull();
		assertThat(directory.resolve("data.mdb")).isRegularFile();
		// No new request: the failed owner already durably selected this dictionary layout.
		ValueStore retried = new ValueStore(directory.toFile(), config());
		try {
			assertLayout(retried, Set.of("spoc", "cspo", "opsc"));
			assertThat(retried.getFormat().getVersion()).isEqualTo(LmdbStoreFormat.CURRENT_VERSION);
		} finally {
			retried.close();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void populatedPreManifestDictionaryStillRequiresItsSavedTermDescriptor(boolean legacy) throws Exception {
		seed(directory, legacy);
		alterNativeManifest(directory, true);
		readProperties(directory).setTripleTermIndexes(null).save();
		byte[] before = Files.readAllBytes(directory.resolve("data.mdb"));
		IOException failure = assertThrows(IOException.class, () -> openAndClose(directory, config()));
		assertThat(failure).hasMessage("Cannot reserve ValueStore startup term-index capacity")
				.hasCauseInstanceOf(SailException.class);
		assertThat(Files.readAllBytes(directory.resolve("data.mdb"))).isEqualTo(before);
		assertThat(readProperties(directory).getTripleTermIndexes()).isNull();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void malformedNativeManifestIsRejectedBeforeBootstrapWrites(boolean legacy) throws Exception {
		seed(directory, legacy);
		alterNativeManifest(directory, false);
		byte[] before = Files.readAllBytes(directory.resolve("data.mdb"));
		IOException failure = assertThrows(IOException.class, () -> openAndClose(directory, config()));
		assertThat(failure).hasMessage("Truncated native triple-term index manifest");
		assertThat(Files.readAllBytes(directory.resolve("data.mdb"))).isEqualTo(before);
		assertThat(TripleIndex.parseIndexSpecList(readProperties(directory).getTripleTermIndexes()))
				.isEqualTo(Set.of("spoc", "cspo", "opsc"));
	}

	private static Seed seed(Path path, boolean legacy) throws Exception {
		LmdbStoreConfig config = config().setTripleTermIndexes("opsc");
		StoreProperties properties = new StoreProperties(path.toFile());
		if (legacy) {
			properties.setVersion(Integer.toString(LmdbStoreFormat.LEGACY_VERSION));
			properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT);
		}
		ValueStore values = legacy ? new ValueStore(path.toFile(), properties, config)
				: new ValueStore(path.toFile(), config);
		var vf = SimpleValueFactory.getInstance();
		TripleTerm term = vf.createTripleTerm(vf.createIRI("urn:startup-capacity:subject"),
				vf.createIRI("urn:startup-capacity:predicate"), vf.createLiteral("nested dictionary owner"));
		long id;
		try {
			values.startTransaction(true);
			id = values.storeValue(term);
			values.commit();
		} finally {
			values.close();
		}
		if (legacy) {
			properties.save();
		}
		return new Seed(term, id);
	}

	private record Seed(TripleTerm term, long id) {
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setValueOverlayEnabled(false).setInlineLiterals(false).setValueDBSize(1L);
	}

	private static void openAndClose(Path path, LmdbStoreConfig config) throws IOException {
		ValueStore values = new ValueStore(path.toFile(), config);
		values.close();
	}

	private static StoreProperties readProperties(Path path) {
		StoreProperties properties = new StoreProperties(path.toFile());
		assertThat(properties.load()).isTrue();
		return properties;
	}

	private static void assertLayout(ValueStore values, Set<String> expected) throws IOException {
		Set<String> indexes = values.getLmdbStats()
				.keySet()
				.stream()
				.filter(name -> name.startsWith("term-"))
				.collect(Collectors.toSet());
		Set<String> expectedDatabases = expected.stream()
				.map(spec -> TripleIndex.nativeDatabaseName("term-" + spec, true))
				.collect(Collectors.toSet());
		assertThat(indexes).isEqualTo(expectedDatabases);
	}

	/** Changes only controlled fixture bytes through a real native writer, with no production hooks. */
	private static void alterNativeManifest(Path path, boolean remove) throws IOException {
		long environment = NULL;
		try (MemoryStack stack = stackPush()) {
			var pointer = stack.mallocPointer(1);
			LmdbUtil.E(mdb_env_create(pointer));
			environment = pointer.get(0);
			LmdbUtil.E(mdb_env_set_maxdbs(environment, 64));
			LmdbUtil.E(mdb_env_open(environment, path.toAbsolutePath().toString(), MDB_NOTLS, 0664));
			LmdbUtil.writeTransaction(environment, (nativeStack, txn) -> {
				var dbi = nativeStack.mallocInt(1);
				LmdbUtil.E(mdb_dbi_open(txn, ValueStore.TERM_INDEX_MANIFEST_DATABASE, 0, dbi));
				if (remove) {
					LmdbUtil.E(mdb_drop(txn, dbi.get(0), true));
				} else {
					MDBVal key = MDBVal.calloc(nativeStack)
							.mv_data(nativeStack.bytes(ValueStore.TERM_INDEX_MANIFEST_KEY));
					MDBVal value = MDBVal.calloc(nativeStack).mv_data(nativeStack.bytes((byte) 1));
					LmdbUtil.E(mdb_put(txn, dbi.get(0), key, value, 0));
				}
				return null;
			});
		} finally {
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}
}
